"use client";
import { Slider as Primitive } from "radix-ui";
import { AnimatePresence,motion } from "motion/react";
import { useId,useState,type ComponentProps } from "react";
import { useAingMotion } from "@/registry/aing/lib/motion";
import { result,toolName,useWebMCPTool,type WebMCPProps } from "@/registry/aing/lib/webmcp";
export type SliderProps=ComponentProps<typeof Primitive.Root>&WebMCPProps;
export function Slider({value,defaultValue=[50],onValueChange,min=0,max=100,step=1,webmcp,toolName:name,className="",...props}:SliderProps){
 const id=useId(),[internal,setInternal]=useState(defaultValue),[active,setActive]=useState(false);const values=value??internal;const {reduced,transition}=useAingMotion();const label=props["aria-label"]??props.name??props.id??"Slider";
 const change=(next:number[])=>{setInternal(next);onValueChange?.(next);};
 useWebMCPTool(webmcp===false?null:{name:toolName("set",id,{webmcp,toolName:name},"",label),description:webmcp?.description??`${label}의 첫 번째 값을 설정합니다.`,inputSchema:{type:"object",properties:{value:{type:"number",minimum:min,maximum:max}},required:["value"],additionalProperties:false},execute:({value:next})=>{if(props.disabled||typeof next!=="number"||!Number.isFinite(next)||next<min||next>max||step<=0||Math.abs((next-min)/step-Math.round((next-min)/step))>1e-7)throw new Error("범위와 간격에 맞는 값을 입력하세요.");if(values.length>1&&next>values[1]-(props.minStepsBetweenThumbs??0)*step)throw new Error("다음 핸들보다 작거나 같아야 합니다.");change([next,...values.slice(1)]);props.onValueCommit?.([next,...values.slice(1)]);return result({value:next});}});
 return <Primitive.Root {...props} min={min} max={max} step={step} value={values} onValueChange={change} onPointerEnter={e=>{setActive(true);props.onPointerEnter?.(e);}} onPointerLeave={e=>{setActive(false);props.onPointerLeave?.(e);}} onFocus={e=>{setActive(true);props.onFocus?.(e);}} onBlur={e=>{setActive(false);props.onBlur?.(e);}} className={`relative flex w-full touch-none select-none items-center py-3 data-[orientation=vertical]:h-44 data-[orientation=vertical]:w-5 data-[orientation=vertical]:flex-col data-[disabled]:opacity-45 ${className}`}><Primitive.Track className="relative h-1.5 w-full grow overflow-hidden rounded-full bg-secondary data-[orientation=vertical]:h-full data-[orientation=vertical]:w-1.5"><Primitive.Range className="absolute h-full rounded-full bg-primary data-[orientation=vertical]:w-full"/></Primitive.Track>{values.map((n,index)=><Primitive.Thumb key={index} aria-label={values.length===1?label:`${label} ${index+1}`} asChild><motion.span whileHover={reduced?{}:{scale:1.2}} whileTap={reduced?{}:{scale:1.3}} transition={transition} className="relative block size-4 rounded-full border border-primary/50 bg-background shadow-xs outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"><AnimatePresence>{active&&<motion.span aria-hidden initial={{opacity:0,y:4,scale:0.9}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:2,scale:0.9}} transition={reduced?{duration:0}:{duration:0.12}} className="absolute -top-9 left-1/2 -translate-x-1/2 rounded-md bg-primary px-2 py-1 font-mono text-[10px] text-primary-foreground">{n}</motion.span>}</AnimatePresence></motion.span></Primitive.Thumb>)}</Primitive.Root>;
}
